  ('3899bc69-1589-46b6-89e7-0815a5193b24', '74e62fb9-998b-4d4b-8dd9-e5050ad43e01', 'new', 'mode', null, 'Naruto: Ninjas Assemble themed mode on reworked Erangel locations.', 'Claim C7 (official press release via GamesPress).', 'unverified', 'medium', 'GamesPress official release', 'https://www.gamespress.com/PUBG-MOBILES-VERSION-45-UPDATE-INTRODUCES-ONE-OF-ITS-BIGGEST-EVER-COLL', '2026-07-21'),
  ('cd919b6e-9742-453b-8711-2ee6a6355eb7', '74e62fb9-998b-4d4b-8dd9-e5050ad43e01', 'new', 'mode', null, 'Sea Odyssey mode returns (underwater ruins, last seen in 3.3).', null, 'unverified', 'low', 'u7buy / EnjoyGM coverage (secondary)', 'https://www.enjoygm.com/blog/pubg-mobile/pubg-mobile-4-5-update', '2026-07-21'),
